contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 minSumVal, uint256 am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSumVal); if (__ESBMC_reverted()) return;
        uint256 preBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 preMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool sufficient = preBal >= am && preBal >= preMinSum;
        bool enoughEther = address(c).balance >= am;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!sufficient || !enoughEther || !reverted);
    }

    receive() external payable {}
}

