import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmount, uint256 minSumVal, uint256 am) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        try c.SetMinSum(minSumVal) {} catch { return; }
        uint256 preBal;
        try c.balances(address(this)) returns (uint256 __r) { preBal = __r; } catch { return; }
        uint256 preMinSum;
        try c.MinSum() returns (uint256 __r) { preMinSum = __r; } catch { return; }
        bool sufficient = preBal >= am && preBal >= preMinSum;
        bool enoughEther = address(c).balance >= am;
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!sufficient || !enoughEther || !reverted);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSumVal, uint256 am) public {
        _run(depositAmount, minSumVal, am);
    }

    receive() external payable {}
}
